{
  "summary": "Gather current contract terms, renewal/price-increase policy, and Acme Cloud Services' performance/SLA history and invoice/currency details, then draft a response addressing the renewal and 12% increase request.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (end date, renewal terms, pricing, currency), any internal policy on renewal price increases, the SLA terms for this vendor, run the SLA credit calculator against their performance/incident records to determine any credits owed to us, check recent invoices for amounts and currency, and if amounts are in USD or another foreign currency use the Currency converter (live) to get current values for comparison.",
      "why": "All facts needed for the reply—contract terms, pricing policy, SLA performance, invoices, and currency conversion—must be pulled together before drafting a response."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the reply to Acme Cloud Services addressing the renewal request: confirm or negotiate the 12% price increase based on policy and market/contract facts, note any SLA credits owed to us that should offset costs, and state the proposed renewal terms for the next 12 months.",
      "why": "The executor synthesizes the gathered facts into the final vendor-facing response for human review and approval."
    }
  ],
  "escalate": null
}
